(()=>{const pages=[['Command Center','/'],['People','/people'],['Recruiting','/recruiting'],['Onboarding','/onboarding'],['Time & Attendance','/time-attendance'],['Payroll & Benefits','/payroll'],['Performance','/performance'],['Approvals','/approvals'],['Analytics','/analytics'],['Offboarding','/offboarding'],['Administration','/admin'],['Account & Password','/password']];function install(){if(document.getElementById('ugaforce-nav'))return;const s=document.createElement('style');s.textContent='#ugaforce-nav{position:fixed;left:12px;bottom:12px;z-index:99999;font:14px system-ui}#ugaforce-nav button{border:0;border-radius:999px;background:#172936;color:white;padding:12px 16px;box-shadow:0 4px 18px #0003;font-weight:700}#ugaforce-nav .menu{display:none;position:absolute;bottom:52px;left:0;background:white;border:1px solid #dde3e8;border-radius:14px;padding:8px;min-width:220px;max-height:65vh;overflow:auto;box-shadow:0 8px 28px #0002}#ugaforce-nav.open .menu{display:block}#ugaforce-nav a{display:block;padding:10px 12px;color:#172936;text-decoration:none;border-radius:9px}#ugaforce-nav a:hover{background:#f1f4f6}@media(min-width:900px){#ugaforce-nav{left:18px;bottom:18px}}';document.head.appendChild(s);const n=document.createElement('div');n.id='ugaforce-nav';n.innerHTML='<div class="menu">'+pages.map(p=>`<a href="${p[1]}">${p[0]}</a>`).join('')+'</div><button type="button">UGAFORCE Menu</button>';n.querySelector('button').onclick=()=>n.classList.toggle('open');document.body.appendChild(n)}document.readyState==='loading'?document.addEventListener('DOMContentLoaded',install):install();})();